/* ═══════════════════════════════════════════════════════════════════════════
 * 环形主页（HELM_PAGE_RING，WP-HELM10/R1-S2 / R1-S7b）
 *
 * R1-S6 几何（页面根坐标，屏幕 y = 页面 y + 24）：
 *   环心 (120,118)、直径 200；扇区厚 16 + 深色外沿 2；hub (30,60,180,116)；
 *   四方位模式名已删（盘心模式名是唯一模式指示）；盘下统计 y=264。
 * 数据全部取真实来源（bicycle_runtime / map_page / myvendor_*），不搬模拟器的
 * `s_recs[]/s_week[]` 假数据。
 *
 * R1-S7b 旋转方式：**EPIC 旋转整层环形图**（不再 CPU 逐帧重摆指针）。
 *   · `art` 是当前模式的静态图（纸底/外圈/24 刻度/12 点方位的选中扇区/指针 T），
 *     模式或主题变化时用 LVGL canvas API 重画一次；
 *   · 动画每帧只做 `myvendor_epic_rotate(art → face, angle10, pivot=中心)` +
 *     `lv_obj_invalidate(face_canvas)`；盘心文字是 canvas 之上的独立对象，不旋转；
 *   · EPIC 不可用（模拟器/硬件没起来）时用同一套 200×200 缓冲做 CPU 最近邻旋转，
 *     日志 `epic=0`；缓冲分配失败则退回 S7 的 CPU 指针动画（旧对象保留、平时隐藏）。
 * ═══════════════════════════════════════════════════════════════════════════ */

#define HELM_RING_CX          120
#define HELM_RING_CY          118
#define HELM_RING_D           200
#define HELM_RING_HUB_X       30
#define HELM_RING_HUB_Y       60
#define HELM_RING_HUB_W       180
#define HELM_RING_HUB_H       116
#define HELM_RING_PTR_R0      74
#define HELM_RING_PTR_R1      96
#define HELM_RING_PTR_CROSS   11
#define HELM_RING_TICK_RIN_M  83  /* 整点刻度内端（100/70 × 旧 58） */
#define HELM_RING_TICK_RIN_m  86  /* 其余刻度内端（100/70 × 旧 60） */
#define HELM_RING_TICK_ROUT   93  /* 刻度外端（≤ 半径−4） */
#define HELM_RING_WEEK_Y      264
#define HELM_RING_BAR_BASE    280
#define HELM_RING_BAR_W       8
#define HELM_RING_BAR_GAP     12
/** @brief 旋转 90° 的时长；EPIC 整层旋转 140 ms ≈ 5~9 帧。 */
#define HELM_RING_ANIM_MS     140

/* ── R1-S7b：环形图（ring art）+ face 双缓冲 ───────────────────────────────
 *
 * art  = 当前模式的静态图，画在 **12 点方位**（扇区/指针都朝上）：
 *        纸底、外圈 2px、24 刻度、16px 选中扇区 + 2px 深色外沿、指针 T。
 * face = canvas 的显示缓冲。静止时 face = rotate(art, mode*90°)。
 *
 * 200×200 RGB565 = 80 KB/块，两块共 160 KB，从 BoardPSRAM 堆分配
 * （board_malloc_psram；板端池满时它会回退 SRAM，`psram=` 日志字段可分辨）。
 * 手动按 32B 对齐（EPIC 要求 ≥16B，32B 是缓存行一半，最稳）。
 * 生命周期 = 进程级（与 `s_climb_cbuf` 同理）：`helm_shell_rebuild()` 只删
 * LVGL 对象，缓冲复用、不重复分配。
 */
#define HELM_RING_ART_W       200
#define HELM_RING_ART_H       200
#define HELM_RING_ART_STRIDE  (HELM_RING_ART_W * (int32_t)sizeof(uint16_t))
#define HELM_RING_ART_BYTES   ((size_t)HELM_RING_ART_STRIDE * HELM_RING_ART_H)
#define HELM_RING_ART_ALIGN   32u

/** @brief 四模式名（顺序 = 扇区方位：0 上、1 右、2 下、3 左）。 */
