static int helm_ring_norm(int a)
{
    a %= 360;
    return (a < 0) ? (a + 360) : a;
}

/** @brief trig(±32767) × r，四舍五入（不用 libm，板端与模拟器同一算法）。 */
static int helm_ring_trig(int32_t v, int r)
{
    int64_t p = (int64_t)v * r;

    if (p >= 0) {
        return (int)((p + 16384) / 32767);
    }
    return (int)((p - 16384) / 32767);
}

/** @brief 角度（0 = 12 点，顺时针）→ 页面根坐标。 */
static void helm_ring_pt(int angle, int r, int * x, int * y)
{
    int a = helm_ring_norm(angle);

    *x = HELM_RING_CX + helm_ring_trig(lv_trigo_sin((int16_t)a), r);
    *y = HELM_RING_CY - helm_ring_trig(lv_trigo_cos((int16_t)a), r);
}

/** @brief 模式身份色：骑行=ok、导航=BAN_NAV（蓝）、记录=NAV（橙）、设置=mute。
