 *        （`HELM_COLOR_BAN_NAV`），否则罗盘上导航与记录同色、分不出来。 */
static uint32_t helm_ring_ink_hex(int mode)
{

    /* 扇区 2px 深色外沿（半径 98..100）。 */
    arc.width = 2;
    arc.color = helm_color(helm_ring_ink_hex(mode));
    arc.opa = LV_OPA_COVER;
    lv_draw_arc(&layer, &arc);

    /* 指针 T（12 点方位）：杆 r=74→96、末端 11px 横杆；3px、圆头。 */
    lv_draw_line_dsc_init(&line);
    line.color = helm_color(HELM_COLOR_INK);
    line.width = 3;
    line.opa = LV_OPA_COVER;
    line.round_start = 1;
    line.round_end = 1;
    helm_ring_pt_art(0, HELM_RING_PTR_R0, &x1, &y1);
    helm_ring_pt_art(0, HELM_RING_PTR_R1, &x2, &y2);
    line.p1.x = x1;
    line.p1.y = y1;
    line.p2.x = x2;
    line.p2.y = y2;
    lv_draw_line(&layer, &line);
    line.p1.x = x2 - HELM_RING_PTR_CROSS;
    line.p1.y = y2;
    line.p2.x = x2 + HELM_RING_PTR_CROSS;
    line.p2.y = y2;
    lv_draw_line(&layer, &line);

    lv_canvas_finish_layer(s_ring_art_cv, &layer);
}

/**
 * @brief 一帧：art --EPIC--> face（RGB565、最近邻、返回时已停）。
 * @return false = EPIC 没执行（不可用/超时），调用方走 CPU 回退。
 */
static bool helm_ring_face_epic(int32_t angle)
{
    if (s_ring_art == NULL || s_ring_face == NULL) {
        return false;
    }

    return myvendor_epic_rotate(s_ring_art, (uint32_t)HELM_RING_ART_STRIDE,
                                HELM_RING_ART_W, HELM_RING_ART_H,
                                s_ring_face, (uint32_t)HELM_RING_ART_STRIDE,
                                HELM_RING_ART_W, HELM_RING_ART_H,
                                helm_ring_norm((int)angle) * 10,
                                HELM_RING_ART_W / 2, HELM_RING_ART_H / 2,
                                HELM_RING_ART_W / 2, HELM_RING_ART_H / 2);
}

/** @brief floor(v / 65536)（v 为负也向下取整；供 CPU 旋转用）。 */
static int32_t helm_ring_floor16(int64_t v)
{
    if (v >= 0) {
        return (int32_t)(v >> 16);
    }
    return (int32_t)(-(((-v) + 65535) >> 16));
}

/**
 * @brief CPU 最近邻回退（仅 EPIC 不可用/超时时走；与 EPIC 同一套语义）。
 *
 * @details 逆向映射：src = R(-θ)·(dst - center) + center，θ 顺时针。
 *          坐标按**像素中心**算（像素 i 覆盖 [i,i+1)，中心 i+0.5）—— 这与
 *          EPIC 的 pivot 语义一致（HAL 的 `EPIC_GetRotatedArea` 用 `w - pivot`），
 *          90° 的整数倍能把 200×200 网格**逐像素**映射回自己，不产生 1px 漂移。
 *          采样越界时保留 face 原像素（= 上一帧的纸色），与 EPIC 的
 *          "背景 = 目的层本身"一致。
 */
static void helm_ring_face_cpu(int32_t angle)
{
    const int a = helm_ring_norm((int)angle);
    const int32_t cs = lv_trigo_cos((int16_t)a);
    const int32_t sn = lv_trigo_sin((int16_t)a);
    const int32_t cx = HELM_RING_ART_W / 2;
    const int32_t cy = HELM_RING_ART_H / 2;
    int32_t y;

    if (s_ring_art == NULL || s_ring_face == NULL) {
        return;
    }

    for (y = 0; y < HELM_RING_ART_H; y++) {
        uint16_t *drow = s_ring_face + (size_t)y * HELM_RING_ART_W;
        const int32_t hy = 2 * y + 1 - 2 * cy;   /* 2 × (dy，以像素中心算) */
        int32_t x;

        for (x = 0; x < HELM_RING_ART_W; x++) {
            const int32_t hx = 2 * x + 1 - 2 * cx;
            const int64_t nx = (int64_t)cs * hx + (int64_t)sn * hy;
            const int64_t ny = -(int64_t)sn * hx + (int64_t)cs * hy;
            const int32_t sx = helm_ring_floor16(nx) + cx;
            const int32_t sy = helm_ring_floor16(ny) + cy;

            if (sx >= 0 && sy >= 0 && sx < HELM_RING_ART_W &&
                sy < HELM_RING_ART_H) {
                drow[x] = s_ring_art[(size_t)sy * HELM_RING_ART_W + (size_t)sx];
            }
        }
    }
}

/** @brief 把 art 转到 face（EPIC 优先，失败/不可用走 CPU），并标脏 canvas。 */
static void helm_ring_face_blit(int32_t angle)
{
    if (s_sh.ring_canvas == NULL || s_ring_face == NULL) {
        return;
    }

    if (!helm_ring_face_epic(angle)) {
        helm_ring_face_cpu(angle);
    }
    lv_obj_invalidate(s_sh.ring_canvas);
}

/**
 * @brief 建 ring art/face 的 canvas 对象（face 可见、art 隐藏）。
 * @return true = canvas 路径可用；false = 走旧对象 + CPU 指针动画。
 */
static bool helm_ring_canvas_build(void)
{
#if defined(__NuttX__)
    /* 板端：EPIC 是唯一可接受的速度。没有 EPIC 时 200×200 的 CPU 整层旋转
     * 每帧要几十 ms（比指针动画还慢），按任务约定直接退回 S7 的 CPU 指针动画；
     * 模拟器（非 __NuttX__）没有 EPIC 是常态，用 CPU 最近邻出中间帧。 */
    if (!myvendor_epic_ready()) {
        printf("[ring] epic unavailable -> cpu pointer anim\n");
        return false;
    }
#endif

    if (!helm_ring_art_alloc()) {
        printf("[ring] art alloc failed -> cpu pointer anim\n");
        return false;
    }

    s_sh.ring_canvas = lv_canvas_create(s_sh.ring);
    lv_canvas_set_buffer(s_sh.ring_canvas, s_ring_face, HELM_RING_ART_W,
                         HELM_RING_ART_H, LV_COLOR_FORMAT_RGB565);
    lv_obj_set_pos(s_sh.ring_canvas,
                   HELM_RING_CX - HELM_RING_ART_W / 2,
                   HELM_RING_CY - HELM_RING_ART_H / 2);
    lv_obj_remove_flag(s_sh.ring_canvas, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_sh.ring_canvas, LV_OBJ_FLAG_SCROLLABLE);

    s_ring_art_cv = lv_canvas_create(s_sh.ring);
    lv_canvas_set_buffer(s_ring_art_cv, s_ring_art, HELM_RING_ART_W,
                         HELM_RING_ART_H, LV_COLOR_FORMAT_RGB565);
    lv_obj_add_flag(s_ring_art_cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(s_ring_art_cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_ring_art_cv, LV_OBJ_FLAG_SCROLLABLE);

    printf("[ring] art %dx%d art=%p face=%p stride=%d align=%u psram=%d\n",
           HELM_RING_ART_W, HELM_RING_ART_H, (void *)s_ring_art,
           (void *)s_ring_face, (int)HELM_RING_ART_STRIDE,
           (unsigned)HELM_RING_ART_ALIGN,
           (board_ptr_in_psram_pool(s_ring_art) &&
            board_ptr_in_psram_pool(s_ring_face)) ? 1 : 0);
    return true;
}

