    }

  /* 只看 IA_BUSY：HAL 的 State 在 IRQ 没人收时可能比硬件"晚"停下
     （LVGL 适配层 `lv_epic_is_hardware_active()` 的注释就是这么说的）。 */
  return (epic->Instance->STATUS & EPIC_STATUS_IA_BUSY_Msk) != 0U;
}

