    Vlayer_x += vl_idx;
    Vlayer_x_trans += vl_idx;

    if ((0 == fg->width) || (0 == fg->height))
    {
        EPIC_DEBUG_PRINT_LAYER_INFO(fg, "Skip invalid video layer");
        return HAL_OK;
