    EPIC_PRINTF("\r\nEPIC_TransformVideoLayer angle=%d,scale_xy=%d,%d, pivot_xy=%d,%d\n",
                rot_cfg->angle, rot_cfg->scale_x, rot_cfg->scale_y,
