/**
 * @brief 一次把扇区/指针/盘心落到目标模式（动画结束帧；无动画的 demo 也走这里）。
 * @details R1-S7b：canvas 路径下扇区/指针已经烘进 ring art —— 这里重画 art
 *          （换模式色）并把 face 转到 `mode*90°`；旧对象（弧/指针/刻度）只在
 *          缓冲分配失败的回退路径里可见，照旧删旧扇区、建新扇区、摆指针。
 */
static void helm_ring_apply(int mode)
{
    int i;

    mode &= 3;

    if (s_sh.ring == NULL) {
        s_sh.ring_mode = (uint8_t)mode;
        return;
    }

    for (i = 0; i < 2; i++) {
        if (s_sh.ring_fill[i] != NULL) {
            lv_obj_delete(s_sh.ring_fill[i]);
            s_sh.ring_fill[i] = NULL;
        }
        if (s_sh.ring_trk[i] != NULL) {
            lv_obj_delete(s_sh.ring_trk[i]);
            s_sh.ring_trk[i] = NULL;
        }
    }

    s_sh.ring_mode = (uint8_t)mode;
    helm_ring_sector_make(mode);
    s_sh.ring_angle = (int32_t)mode * 90;
    helm_ring_pointer_layout(s_sh.ring_angle);
    helm_ring_paint_mode(mode);
    helm_ring_paint_values(bicycle_runtime_get());

    if (s_sh.ring_canvas != NULL) {
        helm_ring_art_draw(mode);
        if (!helm_ring_face_epic(s_sh.ring_angle)) {
            helm_ring_face_cpu(s_sh.ring_angle);
        }
        /* 动画刚跑完时只标脏转子（和上一帧并集）；首次摆页/回退路径整幅标脏。 */
        if (s_ring_rotor_prev_ok) {
            helm_ring_invalidate_rotor(s_sh.ring_angle);
        } else {
            lv_obj_invalidate(s_sh.ring_canvas);
            helm_ring_rotor_bbox((int)s_sh.ring_angle, &s_ring_rotor_prev);
            s_ring_rotor_prev_ok = true;
        }
    }
}

/** @brief 转子（扇区 ±26° + 指针 T）在页面坐标下的包围盒（含 4px 余量）。 */
static void helm_ring_rotor_bbox(int angle, lv_area_t * a)
{
    const int r_out = HELM_RING_D / 2;       /* 100 */
    const int r_in = r_out - 16;             /* 84：扇区内沿 */
    const int edges[2] = { angle - 26, angle + 26 };
    int32_t minx = 0x7FFFFFFF;
    int32_t miny = 0x7FFFFFFF;
    int32_t maxx = -0x7FFFFFFF;
    int32_t maxy = -0x7FFFFFFF;
    int i;

    for (i = 0; i < 2; i++) {
        int x;
        int y;

        helm_ring_pt(edges[i], r_in, &x, &y);
        minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
        miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
        helm_ring_pt(edges[i], r_out, &x, &y);
        minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
        miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
    }
    /* 指针杆 + 横杆两端（横杆 11px ≈ 在 r=96 上 ±7°）。 */
    {
        static const int pa[2] = { -7, 7 };
        int x;
        int y;

        helm_ring_pt(angle, HELM_RING_PTR_R0, &x, &y);
        minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
        miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
        for (i = 0; i < 2; i++) {
            helm_ring_pt(angle + pa[i], HELM_RING_PTR_R1, &x, &y);
            minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
            miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
        }
    }

    a->x1 = (int32_t)minx - 4;
    a->y1 = (int32_t)miny - 4;
    a->x2 = (int32_t)maxx + 4;
    a->y2 = (int32_t)maxy + 4;
}

/** @brief 只把转子（旧角 ∪ 新角）的包围盒标脏；刻度/外圈/盘心不跟着刷。
 *  @details 整张 200×200 标脏在板端是 ~80 ms/帧（panel flush 40k px），
 *           这正是"转起来卡"的根因；转子脏区通常只有 4~10k px。 */
static void helm_ring_invalidate_rotor(int32_t angle)
{
    lv_area_t a;
    lv_area_t u;
    lv_area_t org;

    if (s_sh.ring_canvas == NULL || s_sh.ring == NULL) {
        return;
    }

    helm_ring_rotor_bbox((int)angle, &a);
    if (s_ring_rotor_prev_ok) {
        u.x1 = LV_MIN(a.x1, s_ring_rotor_prev.x1);
        u.y1 = LV_MIN(a.y1, s_ring_rotor_prev.y1);
        u.x2 = LV_MAX(a.x2, s_ring_rotor_prev.x2);
        u.y2 = LV_MAX(a.y2, s_ring_rotor_prev.y2);
    } else {
        u = a;
    }

    lv_obj_get_coords(s_sh.ring, &org);
    u.x1 += org.x1;
    u.x2 += org.x1;
    u.y1 += org.y1;
    u.y2 += org.y1;
    lv_obj_invalidate_area(s_sh.ring_canvas, &u);

    s_ring_rotor_prev = a;
    s_ring_rotor_prev_ok = true;
}

/**
 * @brief 动画帧：整层 EPIC 旋转 + **只标脏转子包围盒**，不重画刻度/文字。
 * @details canvas 路径：每帧一次 `myvendor_epic_rotate(art → face)`；EPIC 不可用
 *          （模拟器）或超时（目的缓冲可能被写了一半）时用 CPU 最近邻重写整幅
 *          face，同一对 200×200 缓冲 —— 中间帧照样出得来，日志 epic=0。
 *          回退路径（art 分配失败）才重摆旧指针（S7 行为）。
 */
static void helm_ring_anim_exec(void * var, int32_t v)
{
    uint32_t now;

    (void)var;
    if (s_sh.ring_canvas != NULL) {
        const int32_t a10 = helm_ring_norm((int)v) * 10;

        if (!myvendor_epic_rotate(s_ring_art, (uint32_t)HELM_RING_ART_STRIDE,
                                  HELM_RING_ART_W, HELM_RING_ART_H,
                                  s_ring_face, (uint32_t)HELM_RING_ART_STRIDE,
                                  HELM_RING_ART_W, HELM_RING_ART_H, a10,
                                  HELM_RING_ART_W / 2, HELM_RING_ART_H / 2,
                                  HELM_RING_ART_W / 2, HELM_RING_ART_H / 2)) {
            s_ring_anim_epic = 0;
            helm_ring_face_cpu(v);
        }
        helm_ring_invalidate_rotor(v);
    } else {
        helm_ring_pointer_layout(v);
    }

    now = lv_tick_get();
    if (s_ring_anim_frames != 0) {
        uint32_t dt = now - s_ring_anim_last;

        if (dt > s_ring_anim_maxdt) {
            s_ring_anim_maxdt = dt;
        }
    }
    s_ring_anim_last = now;
    s_ring_anim_frames++;
}

